/* Source: src/kernel/scrollbars.css */
/*
 * v7 固定全局无滚动条外观内核。
 * 只隐藏浏览器滚动条外观，不修改 overflow、touch-action、pointer-events，
 * 不隐藏滚动容器、跳转键、功能按钮或 input[type="range"]。
 * 全局 * 是本项目唯一允许的无边界选择器例外，不得增加其他声明。
 */
::-webkit-scrollbar {
    display: none !important;
}

* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

/* Source: src/tokens.css */
:root {
  --td-paper: #fffafd;
  --td-backdrop: #eee7ff;
  --td-pink: #ffe3f2;
  --td-blue: #e1f3ff;
  --td-ink: #3f137c;
  --td-muted: #7653b0;
  --td-line: #ab8de5;
  --td-focus: #702bbc;
  --td-disabled: #ece3f5;
  --td-body-font: "Songti SC", "SimSun", "Noto Serif CJK SC", serif;
  --td-ui-font: "Microsoft YaHei", "PingFang SC", sans-serif;
  --td-avatar-width: 240px;
  --td-avatar-height: 180px;
  --st-theme-mobile-reading-width: 100%;
  --st-theme-mobile-reading-padding: 12px;
  --topBarIconSize: 24px;
  --topBarBlockSize: 52px;
  --bottomFormIconSize: 24px;
  --bottomFormBlockSize: 40px;
}
@media (max-width: 700px) {
  :root {
    --td-avatar-width: 144px;
    --td-avatar-height: 144px;
    --topBarIconSize: 21px;
    --topBarBlockSize: 46px;
    --bottomFormIconSize: 23px;
    --bottomFormBlockSize: 36px;
  }
}

/* Source: src/windows/background.css */
/* Separate page layer; no background-setting writes. Artwork deferred to asset stage. */
body { background-color: var(--td-backdrop); }
#bg1 {
  background-color: var(--td-backdrop);
  background-image: none !important;
}

/* Source: src/chat-layout.css */
/* First layout slice: ornament artwork remains a separate required stage. */
#chat {
  background: var(--td-backdrop);
  color: var(--td-ink);
  text-shadow: none;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  gap: 12px;
  padding: 12px 8px;
  min-height: 0;
  max-height: none;
  flex: 1 1 0;
}
#chat .mes[is_system="false"] {
  flex-direction: column;
  align-items: stretch;
  flex-shrink: 0;
  inline-size: 100%;
  min-inline-size: 0;
  box-sizing: border-box;
  margin: 0;
  padding: 18px 22px 16px;
  border: 2px solid var(--td-line);
  border-radius: 5px;
  background: var(--td-paper);
  color: var(--td-ink);
  text-shadow: none;
  box-shadow: none;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper {
  align-self: center;
  inline-size: 100%;
  min-inline-size: 0;
  margin-inline: auto;
  padding: 16px 0 20px;
  box-sizing: border-box;
  text-align: center;
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar {
  inline-size: var(--td-avatar-width);
  block-size: var(--td-avatar-height);
  max-inline-size: 100%;
  margin-inline: auto;
  padding: 5px;
  box-sizing: border-box;
  border: 2px solid var(--td-line);
  border-radius: 12px;
  background: var(--td-blue);
  opacity: 1;
  flex: none;
}
#chat .mes[is_user="true"][is_system="false"] > .mesAvatarWrapper > .avatar {
  background: var(--td-pink);
}
#chat .mes[is_system="false"] > .mesAvatarWrapper > .avatar > img {
  inline-size: 100%;
  block-size: 100%;
  max-inline-size: 100%;
  object-fit: cover;
  border: 1px solid var(--td-line);
  border-radius: 6px;
  box-shadow: none;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] > .mes_block {
  inline-size: 100%;
  min-inline-size: 0;
  padding-inline: 0;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name {
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex1 {
  justify-content: center;
  min-inline-size: 0;
  inline-size: 100%;
}
#chat .mes[is_system="false"] > .mes_block > .ch_name > .flex1 > .alignItemsBaseline {
  justify-content: center;
  align-items: center;
  flex-direction: column;
  min-inline-size: 0;
  max-inline-size: 100%;
  gap: 4px;
}
#chat .mes[is_system="false"] .name_text {
  color: var(--td-ink);
  font-family: var(--td-body-font);
  font-size: 1.25em;
  overflow-wrap: anywhere;
  text-align: center;
}
#chat .mes[is_system="false"] .timestamp {
  color: var(--td-muted);
  font-family: var(--td-ui-font);
  font-size: .8em;
  font-weight: 400;
}
#chat .mes[is_system="false"] > .mes_block > .mes_text {
  inline-size: 100%;
  max-inline-size: 100%;
  min-inline-size: 0;
  margin-inline: auto !important;
  padding: 12px 14px 4px;
  box-sizing: border-box;
}
#chat .mes[is_system="false"] :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
  color: var(--td-muted);
  font-size: .75em;
  text-shadow: none;
}
@media (max-width: 700px) {
  #chat { padding: 8px 6px; gap: 10px; }
  #chat .mes[is_system="false"] {
    padding: 12px 8px;
    flex-direction: column;
    align-items: stretch;
  }
  #chat .mes[is_system="false"] > .mesAvatarWrapper {
    padding-block: 10px 14px;
    align-self: center;
    margin-inline: auto;
  }
  #chat .mes[is_system="false"] > .mes_block {
    inline-size: 100%;
    min-inline-size: 0;
  }
  #chat .mes[is_system="false"] > .mes_block > .mes_text {
    inline-size: min(100%, var(--st-theme-mobile-reading-width));
    max-inline-size: 100%;
    margin-inline: auto !important;
    padding-inline: var(--st-theme-mobile-reading-padding) !important;
    box-sizing: border-box;
  }
}

/* Source: src/full-text.css */
#chat .mes[is_system="false"] .mes_text {
  font-family: var(--td-body-font);
  font-size: 1em;
  font-weight: 400;
  line-height: 1.85;
  color: var(--td-ink);
  text-align: start;
  overflow-wrap: anywhere;
}
#chat .mes[is_system="false"] .mes_text p { margin-block: 0 0.8em; }
#chat .mes[is_system="false"] .mes_text p:last-child { margin-bottom: 0; }
#chat .mes[is_system="false"] .mes_text :is(em, i, q) { color: var(--td-muted); }
#chat .mes[is_system="false"] .mes_text :is(strong, h1, h2, h3) { color: var(--td-ink); }
#chat .mes[is_system="false"] .mes_text a { color: var(--td-focus); text-decoration: underline; }
#chat .mes[is_system="false"] .mes_text blockquote {
  border-inline-start: 3px solid var(--td-line);
  margin-inline: 0;
  padding-inline: 1em;
  color: var(--td-muted);
}

/* Source: src/windows/topbar.css */
#top-settings-holder {
  background: var(--td-paper);
  border: 2px solid var(--td-line);
  border-radius: 5px;
  box-sizing: border-box;
}
#top-settings-holder .drawer-icon {
  color: var(--td-ink);
  opacity: 1;
  filter: none;
  text-shadow: none;
  box-shadow: none;
  padding: 5px 3px;
  line-height: 1;
  box-sizing: border-box;
  border-radius: 3px;
}
#top-settings-holder .drawer-icon:is(:hover, .openIcon) {
  background: var(--td-pink);
  color: var(--td-focus);
}
#top-settings-holder .drawer-icon:focus-visible {
  outline: 2px solid var(--td-focus);
  outline-offset: 2px;
}

/* Source: src/windows/input.css */
#send_form {
  background: var(--td-paper);
  border: 2px solid var(--td-line);
  border-radius: 5px;
  padding: 7px 8px;
  box-sizing: border-box;
  height: auto;
  backdrop-filter: none;
  box-shadow: none;
}
#send_form #nonQRFormItems {
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}
#send_form :is(#leftSendForm, #rightSendForm) {
  padding: 0;
  flex: 0 1 auto;
  max-inline-size: 100%;
  flex-wrap: wrap;
}
#send_form #send_textarea {
  color: var(--td-ink);
  background-color: var(--td-paper);
  border-inline: 1px solid var(--td-line);
  border-bottom: 1px solid var(--td-line);
  border-radius: 4px;
  padding: 7px 9px;
  min-inline-size: 0;
  flex: 1 1 10em;
  font-family: var(--td-body-font);
  font-size: 1em;
  line-height: 1.6;
  text-shadow: none;
  box-shadow: none;
}
#send_form #send_textarea::placeholder { color: var(--td-muted); opacity: 1; }
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate, .stscript_btn) {
  color: var(--td-ink);
  opacity: 1;
  filter: none;
  text-shadow: none;
  box-shadow: none;
  border-radius: 3px;
}
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate, .stscript_btn):hover {
  background-color: var(--td-pink);
  color: var(--td-focus);
  opacity: 1;
}
#send_form :is(#options_button, #extensionsMenuButton, #send_but, #mes_stop, #mes_continue, #mes_impersonate, .stscript_btn):focus-visible {
  outline: 2px solid var(--td-focus);
  outline-offset: -2px;
}
#send_form:has(#send_textarea:focus-visible) {
  border-color: var(--td-focus);
  outline: 2px solid var(--td-focus);
  outline-offset: -2px;
}
#send_form.no-connection { border-style: dashed; }

/* Source: src/windows/message-controls.css */
#chat .mes[is_system="false"] .ch_name > :is(.mes_buttons, .mes_edit_buttons) {
  order: -1;
  align-self: stretch;
  flex-wrap: wrap;
  justify-content: flex-end;
  min-inline-size: 0;
  max-inline-size: 100%;
  gap: 5px;
  filter: none;
  text-shadow: none;
  box-shadow: none;
}
#chat .mes[is_system="false"] .extraMesButtons { flex-wrap: wrap; }
#chat .mes[is_system="false"] :is(.mes_button, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button) {
  color: var(--td-ink);
  opacity: 1;
  filter: none;
  text-shadow: none;
  box-shadow: none;
  border-radius: 4px;
}
#chat .mes[is_system="false"] :is(.mes_button, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):hover {
  color: var(--td-focus);
  background-color: var(--td-pink);
}
#chat .mes[is_system="false"] :is(.mes_button, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):focus-visible {
  outline: 2px solid var(--td-focus);
  outline-offset: -2px;
}
#chat .mes[is_system="false"] :is(.mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button) {
  background-color: var(--td-blue);
  border: 1px solid var(--td-line);
}
#chat .mes[is_system="false"] :is(.mes_edit_cancel.menu_button, .mes_reasoning_edit_cancel) {
  background-color: var(--td-pink);
}
#chat .mes[is_system="false"] :is(.mes_button, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):is(:disabled, [aria-disabled="true"]) {
  color: var(--td-muted);
  background-color: var(--td-disabled);
  border: 1px dashed var(--td-muted);
  opacity: 1;
}
#chat .mes[is_system="false"] :is(.edit_textarea, .reasoning_edit_textarea) {
  inline-size: 100%;
  max-inline-size: 100%;
  box-sizing: border-box;
  background: var(--td-paper);
  color: var(--td-ink);
  border: 1px solid var(--td-line);
  border-radius: 4px;
  padding: 10px;
  font-family: var(--td-body-font);
  line-height: 1.8;
  opacity: 1;
  filter: none;
  text-shadow: none;
  box-shadow: none;
}
#chat .mes[is_system="false"] :is(.edit_textarea, .reasoning_edit_textarea):focus-visible {
  outline: 2px solid var(--td-focus);
  outline-offset: -2px;
}

/* Source: src/fallback.css */
/* No remote dependencies in the layout slice. Native icons and real avatar
   image remain the only foreground image sources; no pseudo-element replacements.
   Pixel background and two distinct wide ornament frames remain required work
   after the user confirms this main-chat layout. */
